WITH latest AS (
  SELECT symbol, close FROM bars WHERE interval='daily' AND ts <= '2024-01-23T14:30:00Z' GROUP BY symbol ORDER BY ts DESC LIMIT 1
),
trend AS (
  SELECT symbol,
    (close - FIRST_VALUE(close) OVER (PARTITION BY symbol ORDER BY ts ROWS UNBOUNDED PRECEDING)) / FIRST_VALUE(close) OVER (PARTITION BY symbol ORDER BY ts ROWS UNBOUNDED PRECEDING) AS change_pct
  FROM bars WHERE interval='daily' AND ts <= '2024-01-23T14:30:00Z' GROUP BY symbol, close, ts ORDER BY symbol, ts
)
SELECT l.symbol, l.close, t.change_pct
FROM latest l JOIN trend t USING (symbol) ORDER BY l.symbol;
